)
select 
 case
	 when "Table Name" ~* any(array['^x.*', '.^et.*']) and "Table Name" not like '%cohort%' then 'EDC'
     when "Table Name" ~* any(array['^subject.*', '^cenduit.*', '.*cohort.*']) then 'IRT'
     when "Table Name" ~* any(array['^pra_.*', '^enroll_.*']) then 'PRA-CTMS'
     when "Table Name" ~* '^q.*' then 'IQVIA-CTMS'
     when "Table Name" ~* '^site_contact.*' then 'Manual-CTMS'
     when "Table Name" ~* '^exelixis_medpace.*' then 'MEDPACE'
     else 'Manual/Unknown'
    end as source,
	case when "Study_id"  = 'All' then 'Global'
    else "Study_id"
    end as study_id,
    md5("Study_id"||"Table Name") as study_id_sk,
    "Table Name",
    "schema name",
    count as record_count,
    load_date::date,
    file_modified_date_s3,
    counts_taken_as_of
FROM raw_data_availability
